	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/actions/{name}", wrapper.GetAction)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/actions/{name}", wrapper.PatchAction)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/actions/{name}/run", wrapper.RunAction)
